<?php
require_once __DIR__.'/../includes/admin.php';admin_required();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$product=['name'=>'','category'=>'','description'=>'','price'=>'','stock'=>0,'is_active'=>1,'image'=>null];if($id){$st=db()->prepare('SELECT * FROM products WHERE id=?');$st->execute([$id]);$found=$st->fetch();if(!$found){flash('Produit introuvable.','error');redirect('index.php');}$product=$found;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$data=valid_product_input($_POST);$image=save_product_image($_FILES['image']??[],$product['image']);$active=isset($_POST['is_active'])?1:0;if($id){$st=db()->prepare('UPDATE products SET name=?,category=?,description=?,price=?,stock=?,image=?,is_active=? WHERE id=?');$st->execute([$data['name'],$data['category'],$data['description'],$data['price'],$data['stock'],$image,$active,$id]);}else{$st=db()->prepare('INSERT INTO products(name,category,description,price,stock,image,is_active)VALUES(?,?,?,?,?,?,?)');$st->execute([$data['name'],$data['category'],$data['description'],$data['price'],$data['stock'],$image,$active]);}flash($id?'Produit modifié.':'Produit ajouté au catalogue.');redirect('index.php');}catch(Throwable$e){$error=$e instanceof RuntimeException?$e->getMessage():'Enregistrement impossible.';$product=array_merge($product,$_POST);}}render_admin_header($id?'Modifier le produit':'Nouveau produit');?>
<div class="admin-title-row"><div><a class="back-link" href="index.php">← Retour au catalogue</a><h1><?=$id?'Modifier le produit':'Ajouter un produit'?></h1></div></div><?php if(isset($error)):?><div class="notice error"><?=e($error)?></div><?php endif?><form class="admin-form" method="post" enctype="multipart/form-data"><?=csrf_field()?><div class="form-grid"><label class="full-field">Nom du produit *<input name="name" required maxlength="160" value="<?=e($product['name'])?>"></label><label>Catégorie *<input name="category" required maxlength="80" value="<?=e($product['category'])?>"></label><label>Prix (XOF) *<input type="number" name="price" required min="0" max="999999999" step="1" value="<?=e((string)$product['price'])?>"></label><label>Stock *<input type="number" name="stock" required min="0" max="1000000" value="<?=e((string)$product['stock'])?>"></label><label class="full-field">Description<textarea name="description" rows="6"><?=e($product['description'])?></textarea></label><label class="full-field">Photo (JPG, PNG ou WEBP · 5 Mo)<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><?php if($product['image']):?><div class="image-preview"><img src="../<?=e(product_image($product['image']))?>" alt=""></div><?php endif?><label class="checkbox-label full-field"><input type="checkbox" name="is_active" <?=$product['is_active']?'checked':''?>> Publier le produit</label></div><div class="form-actions"><button class="button button-primary"><?=$id?'Enregistrer':'Créer le produit'?></button><a class="button button-outline" href="index.php">Annuler</a></div></form><?php render_admin_footer();?>
